# Kurs Fahrzeugdiagnose: OBD und UDS
from common import *

M1 = M("diag.m1", 1, "Warum Fahrzeuge sich selbst prüfen", "On-Board- und Off-Board-Diagnose, Geschichte der OBD und der Weg eines Fehlers.", [
 L("diag.m1.l1", "Diagnose: Was und wofür?", 5, [
  "Ein modernes Fahrzeug hat dutzende Steuergeräte. Jedes überwacht seine Sensoren, Aktoren und Funktionen und merkt sich, was schiefgeht. Das nennt man Diagnose.",
  "## On-Board und Off-Board",
  "On-Board-Diagnose läuft im Fahrzeug selbst: Überwachungen erkennen Fehler, speichern sie und schalten bei Bedarf eine Warnleuchte ein. Off-Board-Diagnose nutzt ein externes Gerät, den Tester. Er liest Fehler aus, zeigt Messwerte, startet Prüfroutinen und programmiert Steuergeräte.",
  "## Drei Zielgruppen",
  "Die Entwicklung braucht Diagnose zum Absichern und Fehlersuchen, die Produktion zum Prüfen und Codieren am Band, die Werkstatt zur Reparatur. Und der Gesetzgeber verlangt, dass abgasrelevante Fehler erkannt und angezeigt werden, damit Fahrzeuge im Alltag sauber bleiben."],
  ["On-Board: Fahrzeug überwacht sich selbst.", "Off-Board: Tester liest aus, misst, programmiert.", "Nutzer: Entwicklung, Produktion, Werkstatt, Gesetzgeber."],
  [S_REIF, S_14229],
  [card("On-Board-Diagnose", "Selbstüberwachung im Fahrzeug: Fehler erkennen, speichern, anzeigen."),
   card("Off-Board-Diagnose", "Diagnose mit externem Tester: auslesen, messen, prüfen, programmieren."),
   card("Tester", "Externes Diagnosegerät oder Software, das mit den Steuergeräten kommuniziert.")],
  [mc("Was ist Off-Board-Diagnose?", ["Diagnose mit einem externen Tester", "Selbstüberwachung im Steuergerät während der Fahrt", "Eine Prüfung nur bei abgestelltem Motor", "Diagnose ausschließlich über das Kombiinstrument"], "Off-Board heißt: Das Werkzeug sitzt außerhalb des Fahrzeugs."),
   multi("Wer nutzt Diagnosefunktionen?", ["Entwicklung", "Produktion am Band", "Werkstatt", "Navigationsdienst"], [0, 1, 2], "Navigation hat mit Diagnose nichts zu tun."),
   mc("Warum verlangt der Gesetzgeber On-Board-Diagnose?", ["Damit Abgasfehler im Alltag auffallen", "Damit Werkstätten mehr Umsatz machen", "Damit Fahrzeuge schneller fahren dürfen", "Damit Steuergeräte weniger Strom brauchen"], "Defekte Abgassysteme sollen nicht unbemerkt bleiben."),
   mc("Was gehört nicht zur Off-Board-Diagnose?", ["Die Überwachung von Zündaussetzern während der Fahrt", "Fehlerspeicher mit einem Tester auslesen", "Ein Steuergerät neu programmieren", "Einen Stellgliedtest in der Werkstatt starten"], "Die Aussetzererkennung läuft im Steuergerät selbst, also on-board."),
   mc("Wofür nutzt die Produktion Diagnose am Band?", ["Prüfen und Codieren der Steuergeräte", "Lackieren der Karosserie", "Tanken der Fahrzeuge", "Planung der Schichten"], "Am Bandende werden Steuergeräte geprüft, codiert und teils programmiert.")]),
 L("diag.m1.l2", "Eine kurze Geschichte der OBD", 6, [
  "Die On-Board-Diagnose kommt aus Kalifornien. Wegen massiver Smogprobleme verlangte die Behörde CARB ab Ende der 1980er-Jahre erste Überwachungen (später OBD I genannt).",
  "## OBD II",
  "Ab Modelljahr 1996 wurde OBD II in den USA für Pkw verpflichtend. Neu waren eine genormte Diagnosebuchse, genormte Fehlercodes und genormte Dienste. Seitdem kann jedes Scan-Tool abgasrelevante Daten jedes Fahrzeugs lesen.",
  "## EOBD in Europa",
  "Europa zog mit der European On-Board Diagnosis (EOBD) nach: für neue Benziner ab 2001, für Diesel-Pkw ab 2003/2004. Die Anforderungen wurden mit jeder Euro-Stufe verschärft, etwa mit Vorgaben zur Überwachungshäufigkeit (IUMPR).",
  "## Heute",
  "Moderne Fahrzeuge nutzen CAN statt der alten K-Leitung, zunehmend auch Ethernet (DoIP). Mit SAE J1979-2 wird OBD auf UDS-Basis umgestellt (oft OBDonUDS genannt). Die Grundidee bleibt: Fehler erkennen, speichern, anzeigen und genormt auslesbar machen."],
  ["OBD stammt aus Kalifornien (CARB).", "OBD II in den USA ab Modelljahr 1996; EOBD in der EU ab 2001 (Benziner).", "Trend: CAN, DoIP und OBD auf UDS-Basis (J1979-2)."],
  [S_CARB, S_J1979, S_1151],
  [card("CARB", "California Air Resources Board: kalifornische Behörde, Vorreiter der OBD-Vorschriften."),
   card("OBD II", "US-Standard der On-Board-Diagnose, Pflicht ab Modelljahr 1996."),
   card("EOBD", "European On-Board Diagnosis: europäisches Gegenstück, Pflicht für neue Benziner ab 2001."),
   card("OBDonUDS", "OBD-Kommunikation auf Basis von UDS nach SAE J1979-2.")],
  [mc("Ab welchem Modelljahr war OBD II in den USA Pflicht?", ["1996", "1988", "2001", "2010"], "1988 kamen erste Vorgaben in Kalifornien, 2001 EOBD für Benziner in der EU."),
   mc("Was brachte OBD II neu?", ["Genormte Buchse, Codes und Dienste", "Erstmals elektronische Einspritzung", "Den ersten Airbag im Pkw", "Die Pflicht zum Katalysator"], "Die Normung machte herstellerübergreifende Scan-Tools möglich."),
   mc("Ab wann galt EOBD für neue Benziner in der EU?", ["2001", "1996", "1992", "2014"], "Diesel-Pkw folgten wenige Jahre später."),
   mc("Was beschreibt SAE J1979-2?", ["OBD-Kommunikation auf UDS-Basis", "Die Form der Diagnosebuchse", "Die Abgasgrenzwerte von Euro 7", "Den LIN-Bus im Fahrzeug"], "Die Buchse ist in SAE J1962 festgelegt."),
   mc("Woher stammt die OBD-Idee?", ["Aus Kalifornien", "Aus Japan", "Aus der EU-Kommission", "Von der Formel 1"], "Die Behörde CARB reagierte auf massive Luftverschmutzung.")]),
 L("diag.m1.l3", "Der Weg eines Fehlers", 6, [
  "Wie wird aus einer kaputten Lambdasonde ein Eintrag, den die Werkstatt liest? Der Weg ist bei fast allen Steuergeräten gleich.",
  "## 1. Überwachung",
  "Eine Diagnosefunktion (Monitor) prüft eine Bedingung, etwa ob die Sondenspannung plausibel ist. Ergebnis: bestanden oder fehlgeschlagen.",
  "## 2. Entprellung und Speicherung",
  "Ein Fehler muss sich bestätigen, bevor er zählt. Danach wird er im Fehlerspeicher als DTC mit Status und Umgebungsdaten abgelegt.",
  "## 3. Reaktion und Anzeige",
  "Das Steuergerät reagiert, etwa mit einem Ersatzwert. Bei abgasrelevanten Fehlern leuchtet die Motorkontrollleuchte (MIL).",
  "## 4. Auslesen und Reparieren",
  "In der Werkstatt liest der Tester DTC, Status und Umgebungsdaten aus. Nach der Reparatur wird der Fehler gelöscht, und die Überwachung muss erneut laufen, um die Reparatur zu bestätigen."],
  ["Monitor → Entprellung → DTC mit Status und Umgebungsdaten.", "Reaktion: Ersatzwert, Notlauf, ggf. Warnleuchte.", "Nach Reparatur: löschen und Überwachung erneut laufen lassen."],
  [S_REIF, S_14229, S_AUTOSAR],
  [card("Monitor", "Diagnosefunktion, die eine Komponente oder Funktion überwacht und bestanden oder fehlgeschlagen meldet."),
   card("DTC", "Diagnostic Trouble Code: gespeicherter Fehlercode mit Status."),
   card("MIL", "Malfunction Indicator Lamp: Motorkontrollleuchte für abgasrelevante Fehler.")],
  [order("Bringe den Weg eines Fehlers in die richtige Reihenfolge.", ["Monitor erkennt Abweichung", "Entprellung bestätigt den Fehler", "DTC wird gespeichert", "Tester liest den Fehler aus", "Reparatur und Löschen"], "Erst wenn sich ein Fehler bestätigt, wird er gespeichert."),
   mc("Was liefert ein Monitor als Ergebnis?", ["Bestanden oder fehlgeschlagen", "Einen fertigen Reparaturauftrag", "Die Uhrzeit des letzten Tankstopps", "Eine neue Softwareversion"], "Monitore melden Prüfergebnisse an das Fehlermanagement."),
   mc("Warum muss die Überwachung nach dem Löschen erneut laufen?", ["Um die Reparatur zu bestätigen", "Weil der Tester sonst blockiert", "Damit die Batterie geladen wird", "Weil die MIL sonst blinkt"], "Erst ein erneutes „bestanden“ zeigt, dass der Fehler wirklich weg ist."),
   mc("Wann leuchtet die Motorkontrollleuchte typischerweise?", ["Bei bestätigten abgasrelevanten Fehlern", "Bei jedem kurzen Störimpuls", "Nur beim Motorstart", "Wenn der Tester angeschlossen ist"], "Kurze Störungen werden entprellt; die MIL kommt bei bestätigten Abgasfehlern."),
   mc("Was speichert das Steuergerät zusätzlich zum Fehlercode?", ["Status und Umgebungsdaten", "Den Namen des Fahrers", "Das Navigationsziel", "Die Radiosender"], "Status und Umgebungsdaten (Freeze Frame) helfen bei der Fehlersuche.")])
])

M2 = M("diag.m2", 1, "Fehlermanagement im Steuergerät", "Monitore, Entprellung, Statusbits, Umgebungsdaten, Alterung und Fahrzyklen.", [
 L("diag.m2.l1", "Monitore und Fahrzyklen", 6, [
  "Nicht jede Überwachung kann jederzeit laufen. Man unterscheidet kontinuierliche und nicht kontinuierliche Monitore.",
  "## Kontinuierlich",
  "Manche Prüfungen laufen ständig, etwa die Erkennung von Kurzschlüssen und Unterbrechungen (oft „Comprehensive Components“ genannt), die Zündaussetzererkennung oder die Überwachung des Kraftstoffsystems.",
  "## Nicht kontinuierlich",
  "Andere brauchen besondere Bedingungen: Die Katalysatorprüfung braucht einen warmen Motor und stabile Fahrt, die Tankentlüftungsprüfung bestimmte Temperaturen und Füllstände. Sie laufen oft nur einmal pro Fahrt.",
  "## Der Fahrzyklus",
  "Viele Regeln beziehen sich auf den Fahrzyklus (Operation Cycle): von Motorstart bis Abstellen, mit bestimmten Mindestbedingungen. Wie oft ein Fehler bestätigt sein muss, wann die MIL angeht und wann ein Fehler altert, wird in Fahrzyklen gezählt."],
  ["Kontinuierlich: z. B. Kurzschluss-/Unterbrechungsprüfung, Aussetzer.", "Nicht kontinuierlich: z. B. Katalysator, Tankentlüftung.", "Viele Regeln zählen in Fahrzyklen."],
  [S_REIF, S_CARB, S_14229],
  [card("Kontinuierlicher Monitor", "Überwachung, die im Betrieb ständig läuft, z. B. elektrische Prüfungen oder Aussetzererkennung."),
   card("Nicht kontinuierlicher Monitor", "Überwachung, die nur unter bestimmten Bedingungen läuft, z. B. Katalysatorprüfung."),
   card("Fahrzyklus (Operation Cycle)", "Zeitraum vom Start bis zum Abstellen; Bezugsgröße für Bestätigung, MIL und Alterung.")],
  [mc("Welcher Monitor läuft typischerweise nicht kontinuierlich?", ["Katalysatorwirkungsgrad", "Kurzschlussprüfung eines Ventils", "Zündaussetzererkennung", "Unterbrechung eines Sensorkreises"], "Die Katalysatorprüfung braucht warmen Motor und stabile Bedingungen."),
   mc("Was ist ein Fahrzyklus?", ["Zeitraum vom Start bis zum Abstellen", "Eine Umdrehung der Kurbelwelle", "Ein Werkstattaufenthalt", "Die Zeit zwischen zwei Inspektionen"], "Auf ihn beziehen sich Bestätigung, MIL-Regeln und Alterung."),
   multi("Welche Prüfungen laufen typischerweise kontinuierlich?", ["Zündaussetzer", "Elektrische Kurzschlussprüfung", "Tankentlüftungs-Dichtheit", "Katalysatorprüfung"], [0, 1], "Tankentlüftung und Katalysator brauchen besondere Bedingungen."),
   mc("Warum läuft die Tankentlüftungsprüfung nicht bei jeder Fahrt?", ["Sie braucht bestimmte Temperaturen und Füllstände", "Sie ist gesetzlich nur jährlich erlaubt", "Sie würde den Motor beschädigen", "Sie braucht einen angeschlossenen Tester"], "Physikalische Randbedingungen müssen stimmen, sonst ist das Ergebnis nicht aussagekräftig."),
   mc("Wozu zählt man Fahrzyklen?", ["Für Bestätigung, Warnleuchte und Alterung", "Für den Kilometerstand", "Für die Kraftstoffanzeige", "Für die Radioempfangsqualität"], "Viele Fehlerregeln sind in Fahrzyklen definiert.")]),
 L("diag.m2.l2", "Entprellung und Statusbits", 7, [
  "Ein einzelnes Fehlerergebnis kann ein Ausreißer sein. Deshalb wird entprellt.",
  "## Entprellverfahren",
  "Beim Zählerverfahren zählt ein Zähler bei jedem Fehlschlag hoch und bei jedem Erfolg herunter. Erreicht er die obere Schwelle, gilt der Fehler im Zyklus als aufgetreten. Beim Zeitverfahren muss die Abweichung eine Mindestzeit anstehen. Beides findet sich zum Beispiel im AUTOSAR-Modul Dem.",
  "## Das Statusbyte nach UDS",
  "Jeder DTC trägt acht Statusbits (ISO 14229): Bit 0 testFailed (aktuell fehlerhaft), Bit 1 testFailedThisOperationCycle, Bit 2 pendingDTC (ausstehend), Bit 3 confirmedDTC (bestätigt), Bit 4 testNotCompletedSinceLastClear, Bit 5 testFailedSinceLastClear, Bit 6 testNotCompletedThisOperationCycle und Bit 7 warningIndicatorRequested (Warnleuchte angefordert).",
  "## Lesen üben",
  "Status 0x2F bedeutet binär 0010 1111: Bits 0, 1, 2, 3 und 5 sind gesetzt. Der Fehler ist also aktuell vorhanden, trat in diesem Zyklus auf, ist ausstehend und bestätigt und seit dem letzten Löschen schon einmal fehlgeschlagen. Eine Warnleuchte ist nicht angefordert (Bit 7 = 0)."],
  ["Entprellen per Zähler oder Zeit.", "8 Statusbits; wichtig: Bit 0 testFailed, Bit 2 pending, Bit 3 confirmed, Bit 7 Warnleuchte.", "Status als Hex-Byte lesen: Bits einzeln auswerten."],
  [S_14229, S_AUTOSAR],
  [card("Zählerentprellung", "Zähler steigt bei Fehlschlag, sinkt bei Erfolg; an der Schwelle gilt der Fehler als aufgetreten."),
   card("Bit 3 confirmedDTC", "Fehler ist bestätigt und dauerhaft gespeichert."),
   card("Bit 7 warningIndicatorRequested", "Der Fehler fordert eine Warnleuchte an."),
   card("Bit 0 testFailed", "Das letzte Prüfergebnis war fehlerhaft.")],
  [mc("Welches Statusbit zeigt einen bestätigten Fehler?", ["Bit 3 confirmedDTC", "Bit 0 testFailed", "Bit 4 testNotCompletedSinceLastClear", "Bit 6 testNotCompletedThisOperationCycle"], "Bit 2 ist pending, Bit 3 confirmed."),
   mc("Ein DTC hat den Status 0x80. Was bedeutet das?", ["Nur die Warnleuchte ist angefordert", "Der Fehler ist aktuell und bestätigt", "Der Test ist seit dem Löschen nicht gelaufen", "Der Fehler wurde gerade gelöscht"], "0x80 = Bit 7 gesetzt, alle anderen 0."),
   num("Ein Status hat genau die Bits 0 und 3 gesetzt. Welcher Dezimalwert ergibt sich?", 9, "", 0, "Bit 0 = 1, Bit 3 = 8; zusammen 9 (0x09)."),
   mc("Wie arbeitet eine Zählerentprellung?", ["Hochzählen bei Fehler, herunter bei Erfolg", "Jeder Fehler wird sofort bestätigt", "Fehler werden nur nachts gezählt", "Der Zähler läuft nur beim Flashen"], "An der oberen Schwelle gilt der Fehler als aufgetreten."),
   mc("Was sagt Bit 4 testNotCompletedSinceLastClear = 1?", ["Seit dem Löschen lief die Prüfung nie vollständig", "Der Fehler ist bestätigt", "Die Warnleuchte ist an", "Der Fehler trat gerade auf"], "Nach dem Löschen ist dieses Bit gesetzt, bis die Prüfung einmal abgeschlossen wurde.")]),
 L("diag.m2.l3", "Umgebungsdaten, Alterung, Verdrängung", 6, [
  "Ein Fehlercode allein sagt wenig. Erst die Umstände machen die Fehlersuche möglich.",
  "## Snapshot und Extended Data",
  "Beim Auftreten speichert das Steuergerät einen Snapshot (Freeze Frame) mit Messwerten wie Drehzahl, Last, Temperatur und Kilometerstand. Erweiterte Daten (Extended Data Records) enthalten Zähler, etwa wie oft der Fehler auftrat oder wie viele Zyklen seither vergangen sind. Ausgelesen werden sie über UDS 0x19 mit eigenen Unterfunktionen.",
  "## Alterung",
  "Wird ein Fehler nicht mehr erkannt, zählt ein Alterungszähler fehlerfreie Zyklen. Ist eine Schwelle erreicht, wird der Eintrag automatisch gelöscht. So verschwinden einmalige, behobene Fehler von selbst.",
  "## Verdrängung",
  "Der Fehlerspeicher hat nur begrenzt Plätze. Ist er voll, entscheidet eine Verdrängungsregel, welcher Eintrag weichen muss, meist nach Priorität und Alter. Abgasrelevante und sicherheitsrelevante Fehler haben hohe Priorität."],
  ["Snapshot: Messwerte beim Auftreten; Extended Data: Zähler und Zusatzinfos.", "Alterung löscht geheilte Fehler nach fehlerfreien Zyklen.", "Voller Speicher → Verdrängung nach Priorität."],
  [S_14229, S_AUTOSAR],
  [card("Snapshot (Freeze Frame)", "Umgebungsdaten zum Zeitpunkt eines Fehlers, z. B. Drehzahl und Temperatur."),
   card("Extended Data Record", "Zusatzdaten zu einem DTC, z. B. Auftretenszähler oder Alterungszähler."),
   card("Verdrängung (Displacement)", "Regel, welcher Eintrag weichen muss, wenn der Fehlerspeicher voll ist.")],
  [mc("Was passiert bei der Alterung eines Fehlers?", ["Er wird nach fehlerfreien Zyklen gelöscht", "Er wird nach einem Jahr zum Hersteller gesendet", "Er wird immer wichtiger", "Er wird in einen anderen DTC umgewandelt"], "Geheilte Fehler sollen nicht ewig im Speicher bleiben."),
   mc("Was speichert ein Snapshot?", ["Messwerte beim Auftreten des Fehlers", "Die Seriennummer des Testers", "Eine Kopie der gesamten Software", "Den Code zum Entsperren"], "Drehzahl, Last, Temperaturen usw. zeigen die Umstände."),
   mc("Was entscheidet die Verdrängungsregel?", ["Welcher Eintrag bei vollem Speicher weicht", "Wann die Warnleuchte blinkt", "Welche Bitrate der Bus nutzt", "Wann der Motor abschaltet"], "Wichtige Fehler sollen nicht von unwichtigen verdrängt werden."),
   mc("Mit welchem UDS-Dienst liest man Snapshots und Extended Data?", ["0x19 ReadDTCInformation", "0x2E WriteDataByIdentifier", "0x11 ECUReset", "0x3E TesterPresent"], "0x19 hat dafür eigene Unterfunktionen."),
   mc("Was enthält ein Extended Data Record typischerweise?", ["Zähler wie Auftretenshäufigkeit", "Ein Foto der Fehlerstelle", "Den Wartungsplan", "Die Garantiebedingungen"], "Zähler helfen, sporadische Fehler einzuschätzen.")])
])

M3 = M("diag.m3", 1, "Fehlercodes lesen", "Aufbau der DTCs nach SAE J2012: Buchstabe, Ziffern, Fehlerart und typische Beispiele.", [
 L("diag.m3.l1", "Aufbau eines DTC", 7, [
  "OBD-Fehlercodes haben ein festes Format, zum Beispiel P0301. Wer es kennt, versteht schon viel, bevor er nachschlägt.",
  "## Der Buchstabe",
  "P steht für Powertrain (Antrieb), C für Chassis (Fahrwerk), B für Body (Karosserie, Innenraum) und U für Network (Kommunikation).",
  "## Die erste Ziffer",
  "0 bedeutet einen genormten Code (SAE/ISO), gleich bei allen Herstellern. 1 bedeutet einen herstellerspezifischen Code. Bei P gibt es außerdem 2 (genormt) und 3 (gemischt).",
  "## Die zweite Ziffer bei P-Codes",
  "Sie nennt das Teilsystem: 1 und 2 Luft-/Kraftstoffzumessung (2 vor allem Einspritzkreise), 3 Zündung und Aussetzer, 4 zusätzliche Abgasregelung (z. B. Katalysator, Abgasrückführung), 5 Geschwindigkeit und Leerlauf, 6 Steuergerät und Ausgänge, 7 bis 9 Getriebe.",
  "## Die letzten beiden Ziffern",
  "Sie kennzeichnen den konkreten Fehler. P0301 heißt: Aussetzer in Zylinder 1 erkannt. P0420: Wirkungsgrad des Katalysators (Bank 1) unter Schwelle.",
  "Probiere unten den Code-Entschlüssler aus."],
  ["Buchstabe: P Antrieb, C Fahrwerk, B Karosserie, U Netzwerk.", "Erste Ziffer: 0 genormt, 1 herstellerspezifisch.", "Bei P: zweite Ziffer = Teilsystem (3 = Zündung/Aussetzer)."],
  [S_J2012],
  [card("P-Code", "Powertrain: Motor und Getriebe."), card("U-Code", "Network: Kommunikationsfehler, z. B. fehlende Botschaft eines Steuergeräts."),
   card("P0xxx", "Genormter Antriebs-Code, bei allen Herstellern gleich."), card("P0301", "Zündaussetzer in Zylinder 1 erkannt."), card("P0420", "Katalysatorwirkungsgrad unter Schwelle (Bank 1).")],
  [mc("Wofür steht U in einem Fehlercode?", ["Netzwerk und Kommunikation", "Unterboden", "Umweltdaten", "Ultraschallsensoren"], "U-Codes betreffen die Kommunikation zwischen Steuergeräten."),
   mc("Was bedeutet die 1 in P1234?", ["Herstellerspezifischer Code", "Genormter Code", "Fehler in Zylinder 1", "Erster Fehler im Speicher"], "0 genormt, 1 herstellerspezifisch."),
   mc("Was beschreibt P0304?", ["Aussetzer in Zylinder 4", "Katalysator Bank 4 defekt", "Lambdasonde 4 unterbrochen", "Getriebestufe 4 fehlerhaft"], "P03xx = Zündung/Aussetzer; 04 = Zylinder 4."),
   mc("Welches Teilsystem kennzeichnet P04xx?", ["Zusätzliche Abgasregelung", "Getriebe", "Zündung und Aussetzer", "Steuergerät und Ausgänge"], "Hier finden sich z. B. Katalysator und Abgasrückführung."),
   mc("Ein Code beginnt mit C. Wo liegt der Fehler?", ["Im Fahrwerk", "In der Karosserie", "In der Kommunikation", "Im Motor"], "C steht für Chassis.")],
  figs=[{"after": 9, "w": "dtc", "cap": "Gib einen Fehlercode ein und sieh, was jedes Zeichen bedeutet."}]),
 L("diag.m3.l2", "UDS-DTCs und Fehlerart", 6, [
  "Im UDS-Fehlerspeicher hat ein DTC drei Byte. Die ersten zwei Byte entsprechen dem fünfstelligen Code nach SAE J2012, das dritte Byte ist die Fehlerart (Failure Type Byte, FTB).",
  "## Vom Hex-Wert zum Code",
  "Die obersten zwei Bit des ersten Bytes geben den Buchstaben an (00 = P, 01 = C, 10 = B, 11 = U). Die übrigen Bits ergeben die vier Ziffern. Aus 0x0301 wird so P0301, aus 0xC100 wird U0100.",
  "## Die Fehlerart",
  "Das FTB präzisiert den Fehler, etwa 0x11 Kurzschluss nach Masse, 0x12 Kurzschluss nach Plus, 0x13 Unterbrechung, 0x1C Spannung außerhalb des Bereichs oder 0x00 ohne nähere Angabe. Ein Code mit FTB, zum Beispiel P0201-13, heißt also: Einspritzventil Zylinder 1, Stromkreis unterbrochen.",
  "## Wer ist zuständig?",
  "Die Bedeutung der Codes ist in SAE J2012 (bzw. ISO 15031-6) festgelegt. Herstellerspezifische Codes stehen in den Diagnosedaten des Herstellers, etwa in ODX-Dateien."],
  ["UDS-DTC = 2 Byte Code + 1 Byte Fehlerart (FTB).", "Obere 2 Bit: 00 P, 01 C, 10 B, 11 U.", "FTB z. B. 0x11 Kurzschluss Masse, 0x12 Kurzschluss Plus, 0x13 Unterbrechung."],
  [S_J2012, S_14229],
  [card("Failure Type Byte (FTB)", "Drittes DTC-Byte, das die Fehlerart angibt, z. B. Unterbrechung."),
   card("FTB 0x13", "Stromkreis unterbrochen (circuit open)."),
   card("U0100", "Kommunikationsverlust zum Motorsteuergerät (ECM/PCM).")],
  [mc("Was steht im dritten Byte eines UDS-DTC?", ["Die Fehlerart (FTB)", "Der Kilometerstand", "Die Anzahl der Fehler", "Das Statusbyte"], "Das Statusbyte wird separat übertragen."),
   mc("Welcher Buchstabe gehört zu den oberen Bits 11?", ["U", "P", "C", "B"], "00 P, 01 C, 10 B, 11 U."),
   mc("Was bedeutet FTB 0x13?", ["Unterbrechung", "Kurzschluss nach Masse", "Kurzschluss nach Plus", "Signal unplausibel"], "0x11 Masse, 0x12 Plus, 0x13 offen."),
   mc("Was wird aus dem Hex-Wert 0x0420?", ["P0420", "C0420", "U0420", "B0420"], "Obere Bits 00 ergeben P."),
   mc("Wo findet man die Bedeutung herstellerspezifischer Codes?", ["In den Diagnosedaten des Herstellers", "In SAE J2012 vollständig", "Auf der OBD-Buchse aufgedruckt", "Im Fahrzeugschein"], "Die Norm beschreibt nur die genormten Codes.")]),
 L("diag.m3.l3", "Typische Codes in der Praxis", 6, [
  "Einige Codes begegnen einem immer wieder. Wichtig ist: Ein Code nennt das Symptom, das die Überwachung sieht, nicht automatisch das defekte Teil.",
  "## Beispiele",
  "P0300 zufällige oder mehrere Aussetzer, P0171 Gemisch zu mager (Bank 1), P0420 Katalysatorwirkungsgrad zu niedrig, P0442 kleines Leck im Tankentlüftungssystem, P0128 Kühlmitteltemperatur unter Regelschwelle (etwa Thermostat), U0100 Kommunikation zum Motorsteuergerät verloren.",
  "## Symptom statt Ursache",
  "P0171 „zu mager“ kann von einem Unterdruckleck, einem verschmutzten Luftmassenmesser, schwacher Kraftstoffpumpe oder undichten Injektoren kommen. P0420 tritt oft auf, weil der Katalysator gealtert ist, kann aber auch von einer fehlerhaften Lambdasonde oder einem Leck vor der Sonde stammen.",
  "## Gute Praxis",
  "Snapshot und Status anschauen, Messwerte prüfen, mit Prüfplänen gezielt eingrenzen und erst dann Teile tauschen. Teiletausch nach Bauchgefühl ist teuer und löst das Problem oft nicht."],
  ["Ein Code beschreibt ein Symptom, nicht zwingend das defekte Teil.", "Beispiele: P0300, P0171, P0420, P0442, U0100.", "Erst Daten prüfen und eingrenzen, dann Teile tauschen."],
  [S_J2012, S_REIF],
  [card("P0171", "System zu mager (Bank 1)."), card("P0442", "Kleines Leck im Kraftstoffverdunstungssystem erkannt."), card("P0300", "Zufällige oder mehrere Zündaussetzer erkannt.")],
  [mc("Welche Aussage über Fehlercodes stimmt?", ["Sie beschreiben ein Symptom", "Sie nennen immer das defekte Bauteil", "Sie sind bei allen Herstellern frei erfunden", "Sie verschwinden nie von selbst"], "Die Ursache muss man oft erst eingrenzen."),
   multi("Was kann P0171 (zu mager) verursachen?", ["Unterdruckleck", "Verschmutzter Luftmassenmesser", "Schwache Kraftstoffpumpe", "Zu volle Scheibenwaschanlage"], [0, 1, 2], "Alles, was zu viel Luft oder zu wenig Kraftstoff bewirkt."),
   mc("Was bedeutet P0300?", ["Mehrere oder zufällige Aussetzer", "Aussetzer nur in Zylinder 3", "Kein Zündfunke beim Start", "Zündspule 3 unterbrochen"], "Die 00 steht für „nicht einem Zylinder zuzuordnen“."),
   mc("Was ist die beste erste Reaktion auf einen DTC?", ["Snapshot und Messwerte prüfen", "Sofort das genannte Teil tauschen", "Den Fehler löschen und abwarten", "Die Batterie abklemmen"], "Daten zeigen, unter welchen Bedingungen der Fehler auftrat."),
   mc("Was meldet U0100?", ["Kommunikation zum Motorsteuergerät verloren", "Batteriespannung zu niedrig", "Kühlmittel zu kalt", "Katalysator verbraucht"], "U-Codes betreffen Netzwerkkommunikation.")])
])

M4 = M("diag.m4", 2, "OBD: Buchse, Dienste und Daten", "Die genormte Schnittstelle, OBD-Dienste, Messwerte (PIDs), MIL und Readiness.", [
 L("diag.m4.l1", "Die OBD-Buchse", 5, [
  "Die 16-polige Diagnosebuchse nach SAE J1962 (bzw. ISO 15031-3) muss in Reichweite des Fahrersitzes liegen, meist unter dem Armaturenbrett.",
  "## Wichtige Pins",
  "Pin 16 ist Batterieplus (Klemme 30), Pin 4 Fahrzeugmasse und Pin 5 Signalmasse. Pin 6 und 14 sind CAN-High und CAN-Low. Pin 7 (und 15) führte bei älteren Fahrzeugen die K-Leitung (ISO 9141, ISO 14230). Die übrigen Pins dürfen Hersteller teils frei belegen, etwa für Ethernet (DoIP).",
  "## Was man darüber erreicht",
  "Genormt sind die abgasrelevanten Daten. Über dieselbe Buchse sprechen Werkstatt-Tester aber auch alle anderen Steuergeräte an, sofern das Gateway den Zugriff zulässt. Viele Hersteller schützen erweiterte Zugriffe inzwischen durch Authentifizierung."],
  ["16-polige Buchse nach SAE J1962 nahe dem Fahrer.", "Pin 16 Plus, 4/5 Masse, 6/14 CAN.", "Erweiterter Zugriff läuft über das Gateway, oft geschützt."],
  [S_J1962],
  [card("SAE J1962", "Norm der 16-poligen OBD-Diagnosebuchse."), card("Pin 6 / Pin 14", "CAN-High / CAN-Low an der OBD-Buchse."), card("Pin 16", "Batterieplus (Dauerplus) an der OBD-Buchse.")],
  [mc("Wie viele Pins hat die OBD-Buchse?", ["16", "8", "12", "24"], "Festgelegt in SAE J1962."),
   mc("Welche Pins führen CAN-High und CAN-Low?", ["6 und 14", "4 und 5", "7 und 15", "1 und 9"], "7 und 15 waren für die K-Leitung."),
   mc("Was liegt an Pin 16?", ["Batterieplus", "Signalmasse", "CAN-High", "Ethernet"], "Darüber versorgen sich viele Scan-Tools."),
   mc("Wo muss die OBD-Buchse liegen?", ["In Reichweite des Fahrersitzes", "Im Motorraum neben der Batterie", "Im Kofferraum", "Hinter dem Kennzeichen"], "Leicht erreichbar für Prüfer und Werkstatt."),
   mc("Wofür stand Pin 7 bei älteren Fahrzeugen?", ["K-Leitung", "CAN-High", "Masse", "Zündung"], "ISO 9141 und ISO 14230 (KWP2000) nutzten die K-Leitung.")]),
 L("diag.m4.l2", "OBD-Dienste und PIDs", 7, [
  "OBD-Anfragen bestehen aus einem Dienst (früher „Mode“) und oft einem Parameter (PID).",
  "## Die wichtigsten Dienste",
  "0x01 aktuelle Daten, 0x02 Freeze-Frame-Daten, 0x03 gespeicherte (bestätigte) DTCs, 0x04 DTCs und Diagnosedaten löschen, 0x06 Ergebnisse der Überwachungstests, 0x07 ausstehende DTCs, 0x08 Steuerung von Bordsystemen, 0x09 Fahrzeuginformationen (z. B. Fahrgestellnummer, Kalibrierkennung CALID und Prüfsumme CVN) und 0x0A permanente DTCs.",
  "## PIDs umrechnen",
  "PID 0x0C liefert die Drehzahl in zwei Byte A und B: Drehzahl = (256 × A + B) ÷ 4. PID 0x0D liefert die Geschwindigkeit direkt in km/h. PID 0x05 liefert die Kühlmitteltemperatur: Wert minus 40 in °C.",
  "## Funktional und physikalisch",
  "Auf CAN fragt ein Scan-Tool meist funktional an (alle OBD-Steuergeräte zugleich, 11-Bit-ID 0x7DF). Die Antworten kommen von 0x7E8 bis 0x7EF. Physikalische Anfragen an ein bestimmtes Steuergerät gehen an 0x7E0 bis 0x7E7."],
  ["Dienste: 01 Daten, 02 Freeze Frame, 03 DTCs, 04 Löschen, 07 pending, 09 Fahrzeuginfo, 0A permanent.", "PID 0x0C: Drehzahl = (256A + B) ÷ 4.", "Funktionale Anfrage an 0x7DF, Antworten ab 0x7E8."],
  [S_J1979],
  [card("Dienst 0x03", "Liest gespeicherte, bestätigte abgasrelevante DTCs."), card("Dienst 0x09", "Fahrzeuginformationen, z. B. VIN, CALID, CVN."),
   card("PID 0x0C", "Motordrehzahl: (256 × A + B) ÷ 4 in 1/min."), card("0x7DF", "Funktionale OBD-Anfrage-ID auf CAN (11 Bit).")],
  [mc("Mit welchem OBD-Dienst liest man ausstehende (pending) Fehler?", ["0x07", "0x03", "0x04", "0x0A"], "0x03 gespeicherte, 0x0A permanente DTCs."),
   num("PID 0x0C liefert A = 0x0F (15) und B = 0xA0 (160). Wie hoch ist die Drehzahl in 1/min?", 1000, "1/min", 0, "(256 × 15 + 160) ÷ 4 = 4000 ÷ 4 = 1000."),
   num("PID 0x05 liefert den Wert 130. Welche Kühlmitteltemperatur in °C ist das?", 90, "°C", 0, "130 − 40 = 90."),
   mc("Welche ID nutzt eine funktionale OBD-Anfrage auf CAN?", ["0x7DF", "0x7E8", "0x100", "0x7FF"], "0x7E8 ff. sind Antworten."),
   mc("Was liefert Dienst 0x09?", ["Fahrzeuginformationen wie die VIN", "Aktuelle Drehzahl", "Gespeicherte Fehler", "Den Befehl zum Löschen"], "Dazu gehören auch CALID und CVN.")]),
 L("diag.m4.l3", "MIL, Readiness und permanente Fehler", 6, [
  "Für die Abgasuntersuchung und die Werkstatt ist wichtig, ob das Fahrzeug fehlerfrei ist und ob alle Prüfungen gelaufen sind.",
  "## Monitorstatus",
  "PID 0x01 von Dienst 0x01 liefert: ob die MIL an ist, wie viele bestätigte Fehler vorliegen und für jeden Monitor, ob er unterstützt wird und ob er seit dem letzten Löschen abgeschlossen ist (Readiness).",
  "## Readiness nach dem Löschen",
  "Löschen setzt alle Monitore auf „nicht abgeschlossen“. Erst nach passenden Fahrten sind sie wieder bereit. Prüfstellen erkennen so, ob jemand kurz vorher Fehler gelöscht hat.",
  "## Permanente DTCs",
  "In den USA gibt es permanente DTCs (Dienst 0x0A): Sie lassen sich nicht per Tester löschen, sondern verschwinden erst, wenn der Monitor selbst wieder „bestanden“ meldet. Ob und wie das in anderen Märkten gilt, hängt von der jeweiligen Vorschrift ab."],
  ["PID 0x01: MIL-Status, Fehleranzahl, Readiness je Monitor.", "Löschen setzt die Readiness zurück.", "Permanente DTCs (USA) verschwinden erst, wenn der Monitor besteht."],
  [S_J1979, S_CARB],
  [card("Readiness", "Status, ob ein Monitor seit dem letzten Löschen vollständig gelaufen ist."), card("Permanenter DTC", "Fehler, der nicht per Tester gelöscht werden kann, sondern erst durch einen bestandenen Monitor."), card("PID 0x01", "Monitorstatus: MIL, Anzahl DTCs, Readiness der Monitore.")],
  [mc("Was zeigt die Readiness eines Monitors?", ["Ob er seit dem Löschen gelaufen ist", "Ob er gerade einen Fehler meldet", "Wie alt das Steuergerät ist", "Ob der Tester verbunden ist"], "Nach dem Löschen sind Monitore zunächst „nicht bereit“."),
   mc("Wie verschwindet ein permanenter DTC?", ["Wenn der Monitor wieder besteht", "Durch Löschen mit Dienst 0x04", "Durch Abklemmen der Batterie", "Nach 24 Stunden automatisch"], "Genau das macht ihn „permanent“."),
   mc("Warum fällt kurz vorher gelöschter Fehlerspeicher bei der Prüfung auf?", ["Die Readiness ist noch nicht erreicht", "Die MIL blinkt dauerhaft", "Der Kilometerstand steht auf null", "Die VIN wird gelöscht"], "Fehlende Readiness verrät das Löschen."),
   mc("Welche Daten liefert PID 0x01?", ["MIL-Status, Fehleranzahl, Readiness", "Drehzahl und Geschwindigkeit", "Fahrgestellnummer und CVN", "Die Freeze-Frame-Daten"], "Er ist die Übersicht über den OBD-Zustand."),
   mc("Was passiert mit der Readiness beim Löschen (Dienst 0x04)?", ["Alle Monitore werden zurückgesetzt", "Sie bleibt unverändert", "Sie wird auf „bereit“ gesetzt", "Nur die MIL wird zurückgesetzt"], "Deshalb ist Löschen vor der Prüfung keine gute Idee.")])
])

M5 = M("diag.m5", 2, "UDS-Grundlagen", "Anfragen und Antworten, Sitzungen, negative Antworten und Zeitverhalten.", [
 L("diag.m5.l1", "Anfrage und Antwort", 6, [
  "Unified Diagnostic Services (ISO 14229) ist die gemeinsame Sprache zwischen Tester und Steuergerät. Das Prinzip ist einfach: Der Tester fragt (Request), das Steuergerät antwortet (Response).",
  "## Aufbau",
  "Das erste Byte ist die Dienstkennung (Service Identifier, SID), etwa 0x22 für ReadDataByIdentifier. Danach folgen Unterfunktion oder Parameter. Beispiel: 22 F1 90 fragt den Datenwert F190 ab, in vielen Fahrzeugen die Fahrgestellnummer.",
  "## Positive Antwort",
  "Die Antwort beginnt mit SID + 0x40: Auf 0x22 kommt 0x62, gefolgt von der Kennung und den Daten, also 62 F1 90 und dann die 17 Zeichen der VIN.",
  "## Negative Antwort",
  "Kann das Steuergerät die Anfrage nicht erfüllen, antwortet es mit 7F, der abgelehnten SID und einem Negative Response Code (NRC), zum Beispiel 7F 22 31: Anfrage außerhalb des gültigen Bereichs.",
  "Probiere unten den UDS-Simulator aus."],
  ["Request: SID + Parameter; positive Response: SID + 0x40.", "Negative Response: 7F + SID + NRC.", "Beispiel: 22 F1 90 → 62 F1 90 + VIN."],
  [S_14229],
  [card("SID", "Service Identifier: erstes Byte einer UDS-Anfrage, bestimmt den Dienst."), card("Positive Response", "Antwort mit SID + 0x40, z. B. 0x62 auf 0x22."), card("Negative Response", "Antwort 7F + abgelehnte SID + NRC."), card("DID F190", "Häufig genutzte Datenkennung für die Fahrgestellnummer (VIN).")],
  [mc("Welches Byte beginnt die positive Antwort auf 0x2E?", ["0x6E", "0x2E", "0x7F", "0xAE"], "0x2E + 0x40 = 0x6E."),
   mc("Was bedeutet die Antwort 7F 22 31?", ["0x22 abgelehnt: Bereich ungültig", "0x22 erfolgreich ausgeführt", "0x31 erfolgreich ausgeführt", "Steuergerät wird zurückgesetzt"], "NRC 0x31 = requestOutOfRange."),
   mc("Was fragt 22 F1 90 typischerweise ab?", ["Die Fahrgestellnummer (VIN)", "Den Fehlerspeicher", "Die Drehzahl", "Den Sicherheitsschlüssel"], "F190 ist in ISO 14229 als VIN-Kennung vorgesehen."),
   mc("Womit beginnt jede UDS-Anfrage?", ["Mit der Dienstkennung (SID)", "Mit der Fahrgestellnummer", "Mit dem Statusbyte", "Mit einer Prüfsumme"], "Die SID bestimmt, was der Tester will."),
   mc("Welches erste Byte hat jede negative Antwort?", ["0x7F", "0x40", "0x00", "0xFF"], "Danach folgen die abgelehnte SID und der NRC.")],
  figs=[{"after": 9, "w": "uds", "cap": "UDS-Simulator: Wähle eine Anfrage und sieh die Antwort des Steuergeräts."}]),
 L("diag.m5.l2", "Sitzungen und Zeitverhalten", 6, [
  "Nicht jeder Dienst ist immer erlaubt. Welche Funktionen verfügbar sind, hängt von der Diagnosesitzung ab.",
  "## Die Standardsitzungen",
  "0x01 Default Session: Grundzustand nach dem Start, nur Basisdienste. 0x03 Extended Session: erweiterte Dienste wie Stellgliedtests oder Schreiben von Daten. 0x02 Programming Session: Software laden. Gewechselt wird mit 0x10, etwa 10 03.",
  "## TesterPresent",
  "Verlässt der Tester eine Nicht-Standardsitzung ohne Meldung, fällt das Steuergerät nach dem S3-Timeout (typisch 5 Sekunden) zurück in die Default Session. Mit TesterPresent (0x3E) hält der Tester die Sitzung offen. 3E 80 unterdrückt dabei die Antwort.",
  "## Antwortzeiten",
  "Das Steuergerät muss innerhalb von P2 antworten (oft 50 ms). Braucht es länger, sendet es die negative Antwort mit NRC 0x78 (responsePending) und hat dann bis P2* Zeit (oft 5 s). 0x78 heißt also nicht Fehler, sondern „bitte warten“."],
  ["Sitzungen: 01 Default, 02 Programming, 03 Extended; Wechsel mit 0x10.", "TesterPresent (0x3E) verhindert den Rückfall nach S3.", "NRC 0x78: Anfrage erhalten, Antwort folgt."],
  [S_14229],
  [card("0x10 DiagnosticSessionControl", "Wechselt die Diagnosesitzung."), card("S3-Timeout", "Zeit, nach der eine Nicht-Standardsitzung ohne Testeraktivität endet (oft 5 s)."), card("NRC 0x78", "responsePending: Anfrage erhalten, Antwort dauert länger."), card("P2 / P2*", "Antwortzeitgrenzen des Steuergeräts: normal (P2) und nach 0x78 verlängert (P2*).")],
  [mc("Was bedeutet NRC 0x78?", ["Anfrage erhalten, Antwort folgt", "Dienst nicht unterstützt", "Sicherheitszugang verweigert", "Falsche Nachrichtenlänge"], "Das Steuergerät bittet um Geduld."),
   mc("Welche Anfrage wechselt in die Extended Session?", ["10 03", "10 01", "11 01", "3E 00"], "0x10 mit Sitzung 0x03."),
   mc("Was passiert ohne TesterPresent in der Extended Session?", ["Rückfall in die Default Session", "Das Steuergerät schaltet ab", "Die Programmiersitzung startet", "Nichts, die Sitzung bleibt ewig"], "Nach dem S3-Timeout endet die Sitzung."),
   mc("Was bewirkt 3E 80?", ["TesterPresent ohne Antwort", "Reset des Steuergeräts", "Löschen aller Fehler", "Wechsel in die Programmiersitzung"], "Bit 7 der Unterfunktion unterdrückt die positive Antwort."),
   mc("In welcher Sitzung startet ein Steuergerät?", ["Default Session", "Extended Session", "Programming Session", "Safety Session"], "Nach Reset oder Start immer die Default Session.")]),
 L("diag.m5.l3", "Negative Response Codes", 6, [
  "Negative Antworten sagen genau, warum etwas nicht geht. Wer die wichtigsten NRCs kennt, findet Fehler im Ablauf schnell.",
  "## Häufige Codes",
  "0x11 serviceNotSupported: Dienst gibt es nicht. 0x12 subFunctionNotSupported: Unterfunktion gibt es nicht. 0x13 incorrectMessageLengthOrInvalidFormat: Länge oder Format falsch. 0x22 conditionsNotCorrect: Bedingungen nicht erfüllt, etwa Motor läuft. 0x24 requestSequenceError: falsche Reihenfolge. 0x31 requestOutOfRange: Parameter oder Kennung ungültig.",
  "## Rund um Sicherheit",
  "0x33 securityAccessDenied: Steuergerät ist gesperrt. 0x35 invalidKey: falscher Schlüssel. 0x36 exceededNumberOfAttempts: zu viele Fehlversuche. 0x37 requiredTimeDelayNotExpired: Wartezeit nach Fehlversuchen läuft noch.",
  "## Sitzung",
  "0x7F serviceNotSupportedInActiveSession: Den Dienst gibt es, aber nicht in dieser Sitzung. 0x7E gilt entsprechend für Unterfunktionen. Lösung: vorher mit 0x10 in die passende Sitzung wechseln."],
  ["0x11/0x12 nicht unterstützt, 0x13 Länge/Format, 0x22 Bedingungen, 0x24 Reihenfolge, 0x31 Bereich.", "Sicherheit: 0x33, 0x35, 0x36, 0x37.", "0x7F/0x7E: in dieser Sitzung nicht erlaubt."],
  [S_14229],
  [card("NRC 0x22", "conditionsNotCorrect: Voraussetzungen nicht erfüllt (z. B. Motor läuft)."), card("NRC 0x33", "securityAccessDenied: geschützte Funktion, Steuergerät nicht entsperrt."), card("NRC 0x7F", "serviceNotSupportedInActiveSession: Dienst in aktueller Sitzung nicht erlaubt."), card("NRC 0x24", "requestSequenceError: Anfrage in falscher Reihenfolge.")],
  [mc("Der Tester sendet 2E in der Default Session und bekommt 7F 2E 7F. Was hilft?", ["Vorher in die Extended Session wechseln", "Die Anfrage einfach wiederholen", "Das Steuergerät stromlos machen", "Den Fehlerspeicher löschen"], "NRC 0x7F: Dienst gibt es, aber nicht in dieser Sitzung."),
   mc("Welcher NRC kommt bei falschem Schlüssel?", ["0x35 invalidKey", "0x33 securityAccessDenied", "0x31 requestOutOfRange", "0x13 incorrectMessageLength"], "0x33 kommt, wenn man ungeschützt Geschütztes versucht."),
   mc("Was bedeutet NRC 0x22?", ["Bedingungen nicht erfüllt", "Dienst nicht unterstützt", "Antwort folgt später", "Kennung ungültig"], "Etwa: Stellgliedtest nicht bei laufendem Motor."),
   mc("Was bedeutet NRC 0x24?", ["Falsche Reihenfolge der Anfragen", "Zu viele Fehlversuche", "Länge der Nachricht falsch", "Sitzung abgelaufen"], "Beispiel: Schlüssel senden, ohne vorher den Seed angefragt zu haben."),
   mc("Nach mehreren falschen Schlüsseln kommt 0x36. Was heißt das?", ["Zu viele Fehlversuche", "Schlüssel ist richtig", "Dienst nicht unterstützt", "Steuergerät beschäftigt"], "Danach folgt meist eine Wartezeit (0x37).")])
])

M6 = M("diag.m6", 2, "UDS im Detail", "Fehlerspeicher lesen, Daten und Routinen, Stellglieder und Zugriffsschutz.", [
 L("diag.m6.l1", "Fehlerspeicher über 0x19", 6, [
  "ReadDTCInformation (0x19) ist der vielseitigste Diagnosedienst. Über Unterfunktionen wählt der Tester, was er sehen will.",
  "## Wichtige Unterfunktionen",
  "0x01 zählt DTCs, die zu einer Statusmaske passen. 0x02 liefert die DTCs selbst mit Status. 0x04 liest einen Snapshot zu einem DTC, 0x06 dessen Extended Data. 0x0A listet alle unterstützten DTCs.",
  "## Die Statusmaske",
  "Mit der Maske filtert man: 19 02 08 liefert alle DTCs, bei denen Bit 3 (confirmed) gesetzt ist. 19 02 FF liefert alle Einträge mit irgendeinem gesetzten Bit. Die Antwort beginnt mit 59 02, gefolgt von der Maske, die das Steuergerät unterstützt (Availability Mask), und dann je DTC drei Byte Code plus ein Byte Status.",
  "## Löschen",
  "ClearDiagnosticInformation (0x14) mit der Gruppe FF FF FF löscht alle Fehler. Dabei werden auch Snapshots, Zähler und die Readiness zurückgesetzt."],
  ["0x19 01 zählen, 02 lesen, 04 Snapshot, 06 Extended Data, 0A alle unterstützten.", "Statusmaske filtert, z. B. 08 = bestätigte Fehler.", "0x14 FF FF FF löscht alles inklusive Zusatzdaten."],
  [S_14229],
  [card("19 02", "ReadDTCInformation: DTCs nach Statusmaske lesen."), card("19 04", "Snapshot-Daten (Freeze Frame) zu einem DTC lesen."), card("14 FF FF FF", "ClearDiagnosticInformation: alle Fehler löschen.")],
  [mc("Welche Anfrage liefert alle bestätigten Fehler?", ["19 02 08", "19 01 FF", "14 FF FF FF", "22 F1 90"], "Maske 0x08 = Bit 3 confirmed."),
   mc("Womit beginnt die positive Antwort auf 19 02?", ["59 02", "19 42", "7F 19", "62 02"], "0x19 + 0x40 = 0x59."),
   mc("Wie viele Byte belegt ein DTC samt Status in der Antwort?", ["4", "2", "3", "8"], "3 Byte DTC + 1 Byte Status."),
   mc("Was wird beim Löschen mit 0x14 zurückgesetzt?", ["DTCs, Zusatzdaten und Readiness", "Nur die Warnleuchte", "Die Software des Steuergeräts", "Die Codierung"], "Deshalb müssen danach Monitore neu laufen."),
   mc("Was liefert 19 06?", ["Extended Data eines DTC", "Die Anzahl der Fehler", "Die Fahrgestellnummer", "Die Softwareversion"], "Extended Data enthält z. B. Zähler.")]),
 L("diag.m6.l2", "Daten, Routinen und Stellglieder", 6, [
  "Neben Fehlern braucht die Werkstatt Messwerte, Prüfabläufe und die Möglichkeit, Teile gezielt anzusteuern.",
  "## Daten lesen und schreiben",
  "ReadDataByIdentifier (0x22) liest Werte über eine 2-Byte-Kennung (DID), etwa Softwareversion, Seriennummer oder Messwerte. WriteDataByIdentifier (0x2E) schreibt, zum Beispiel Codierung oder Anlernwerte. Bereiche wie F1xx sind in ISO 14229 für Identifikationsdaten vorgesehen.",
  "## Routinen",
  "RoutineControl (0x31) startet (01), stoppt (02) oder fragt Ergebnisse ab (03), jeweils mit einer 2-Byte-Routinekennung. Beispiele: Selbsttest, Drosselklappe anlernen, Speicher löschen vor dem Flashen, Prüfsumme prüfen.",
  "## Stellglieder",
  "InputOutputControlByIdentifier (0x2F) übernimmt einen Ausgang vorübergehend: zum Beispiel Lüfter auf 50 % setzen (shortTermAdjustment, 03) und danach die Kontrolle zurückgeben (returnControlToECU, 00). So prüft man, ob der Aktor mechanisch und elektrisch funktioniert."],
  ["0x22/0x2E: Daten über DIDs lesen und schreiben.", "0x31: Routinen starten (01), stoppen (02), Ergebnis (03).", "0x2F: Ausgänge vorübergehend übernehmen; 00 gibt die Kontrolle zurück."],
  [S_14229],
  [card("DID", "Data Identifier: 2-Byte-Kennung eines Datenwerts."), card("0x31 RoutineControl", "Startet, stoppt oder liest Ergebnisse von Routinen im Steuergerät."), card("0x2F 03", "shortTermAdjustment: Ausgang vorübergehend auf einen Wert setzen."), card("0x2F 00", "returnControlToECU: Kontrolle an das Steuergerät zurückgeben.")],
  [mc("Mit welcher Unterfunktion startet man eine Routine über 0x31?", ["01", "02", "03", "00"], "02 stoppt, 03 liefert das Ergebnis."),
   mc("Was tut 2F … 00?", ["Gibt die Kontrolle ans Steuergerät zurück", "Schaltet den Ausgang dauerhaft ab", "Löscht den Fehlerspeicher", "Setzt die Sitzung zurück"], "returnControlToECU beendet den Stellgliedtest."),
   mc("Wofür eignet sich RoutineControl?", ["Drosselklappe anlernen", "Fahrgestellnummer lesen", "Sitzung wechseln", "Fehler zählen"], "Routinen sind Abläufe im Steuergerät."),
   mc("Wie lang ist ein DID?", ["2 Byte", "1 Byte", "3 Byte", "4 Byte"], "Etwa F1 90 für die VIN."),
   mc("Welcher Dienst schreibt eine Codierung?", ["0x2E WriteDataByIdentifier", "0x22 ReadDataByIdentifier", "0x2F InputOutputControl", "0x19 ReadDTCInformation"], "Codierwerte liegen hinter DIDs.")]),
 L("diag.m6.l3", "Zugriffsschutz: 0x27 und 0x29", 7, [
  "Manche Funktionen sind gefährlich, wenn jeder sie nutzen kann: Software laden, Wegfahrsperre anlernen, Kilometerstand, sicherheitsrelevante Codierung. Deshalb sind sie geschützt.",
  "## SecurityAccess (0x27)",
  "Der klassische Weg: Der Tester fordert mit einer ungeraden Unterfunktion (z. B. 27 01) einen Zufallswert an, den Seed. Er berechnet daraus mit einem geheimen Algorithmus den Key und sendet ihn mit der folgenden geraden Unterfunktion (27 02). Stimmt er, ist das Steuergerät für diese Stufe entsperrt.",
  "## Schwächen",
  "Ist der Algorithmus symmetrisch und in vielen Testern hinterlegt, kann er durchsickern. Zu kurze Seeds oder fehlende Sperrzeiten erleichtern Angriffe.",
  "## Authentication (0x29)",
  "Seit der Ausgabe 2020 von ISO 14229 gibt es 0x29. Damit authentisiert sich der Tester zum Beispiel über Zertifikate (PKI) und beweist den Besitz eines privaten Schlüssels. Rechte lassen sich pro Rolle vergeben, etwa Werkstatt oder Entwicklung.",
  "## Weitere Hilfsdienste",
  "Beim Flashen schaltet der Tester mit CommunicationControl (0x28) normale Botschaften ab und mit ControlDTCSetting (0x85) die Fehlerspeicherung, damit keine Folgefehler entstehen."],
  ["0x27: Seed anfordern (ungerade), Key senden (gerade).", "0x29: Authentisierung z. B. per Zertifikat, rollenbasiert.", "0x28 und 0x85 schalten Kommunikation und Fehlerspeicherung beim Flashen ab."],
  [S_14229],
  [card("Seed", "Zufallswert, den das Steuergerät bei 0x27 an den Tester schickt."), card("Key", "Aus dem Seed berechneter Schlüssel, den der Tester zurücksendet."), card("0x29 Authentication", "UDS-Dienst zur Authentisierung, z. B. mit Zertifikaten."), card("0x85 ControlDTCSetting", "Schaltet die Speicherung von Fehlern vorübergehend ab oder an.")],
  [order("Ordne den SecurityAccess-Ablauf.", ["Tester sendet 27 01", "Steuergerät sendet Seed", "Tester berechnet Key", "Tester sendet 27 02 mit Key", "Steuergerät ist entsperrt"], "Ungerade Unterfunktion: Seed anfordern; gerade: Key senden."),
   mc("Welche Unterfunktion fordert den Seed an?", ["Eine ungerade, z. B. 01", "Eine gerade, z. B. 02", "Immer 00", "Immer FF"], "Gerade Unterfunktionen senden den Key."),
   mc("Was ist ein Vorteil von 0x29 gegenüber 0x27?", ["Zertifikate statt geteiltem Geheimalgorithmus", "Kürzere Anfragen auf dem Bus", "Kein Schlüssel nötig", "Funktioniert nur ohne Sitzung"], "Asymmetrische Verfahren schützen besser vor durchgesickerten Algorithmen."),
   mc("Warum schaltet man beim Flashen 0x85 ab?", ["Um Folgefehler im Speicher zu vermeiden", "Um die Bitrate zu erhöhen", "Um den Seed zu verkürzen", "Um die VIN zu ändern"], "Ohne normale Kommunikation würden andere Steuergeräte Fehler speichern."),
   mc("Welche Funktion ist typischerweise geschützt?", ["Software laden", "Fahrgestellnummer lesen", "TesterPresent senden", "Default Session wählen"], "Programmieren kann Sicherheit und Abgasverhalten verändern.")])
])

M7 = M("diag.m7", 3, "Transport und Werkzeuge", "ISO-TP auf CAN, DoIP auf Ethernet, Diagnosedaten (ODX, OTX) und SOVD.", [
 L("diag.m7.l1", "ISO-TP: lange Nachrichten auf CAN", 7, [
  "Ein CAN-Frame trägt 8 Byte (CAN FD bis 64). Diagnoseantworten sind oft länger, eine VIN allein hat 17 Zeichen. ISO 15765-2 (ISO-TP) zerlegt deshalb lange Nachrichten.",
  "## Rahmentypen",
  "Single Frame (SF): ganze Nachricht passt in einen Frame. First Frame (FF): erster Teil einer langen Nachricht mit der Gesamtlänge. Consecutive Frame (CF): Folgeteile mit laufender Nummer 1, 2, … 15, 0, 1, … Flow Control (FC): Der Empfänger sagt, wie viele Frames am Stück kommen dürfen (Block Size) und mit welchem Mindestabstand (STmin).",
  "## Ein Beispiel",
  "Der Tester fragt 22 F1 90 (Single Frame). Die Antwort mit 20 Byte kommt als First Frame mit Länge 20 und den ersten 6 Byte, der Tester sendet Flow Control, dann folgen zwei Consecutive Frames.",
  "## Grenzen",
  "Klassisch sind bis zu 4095 Byte pro Nachricht möglich; neuere Ausgaben erlauben mit erweitertem First Frame deutlich mehr. Fürs schnelle Flashen großer Software nutzt man heute CAN FD oder Ethernet."],
  ["ISO-TP zerlegt lange Nachrichten: SF, FF, CF, FC.", "Flow Control steuert Blockgröße und Abstand.", "Klassisch bis 4095 Byte pro Nachricht."],
  [S_15765],
  [card("Single Frame", "ISO-TP-Rahmen für Nachrichten, die in einen CAN-Frame passen."), card("First Frame", "Erster Rahmen einer langen Nachricht mit Gesamtlänge."), card("Consecutive Frame", "Folgerahmen mit laufender Sequenznummer."), card("Flow Control", "Rahmen des Empfängers mit Blockgröße und Mindestabstand (STmin).")],
  [order("Ordne den Ablauf einer langen Antwort.", ["First Frame vom Steuergerät", "Flow Control vom Tester", "Consecutive Frame 1", "Consecutive Frame 2"], "Ohne Flow Control dürfen keine Folgerahmen kommen."),
   mc("Was enthält der First Frame?", ["Die Gesamtlänge der Nachricht", "Nur die Sequenznummer", "Die Blockgröße", "Die Fahrgestellnummer"], "Damit weiß der Empfänger, wie viel noch kommt."),
   mc("Wer sendet den Flow-Control-Rahmen?", ["Der Empfänger der langen Nachricht", "Immer das Steuergerät", "Das Gateway", "Der Sender der langen Nachricht"], "Der Empfänger steuert das Tempo."),
   mc("Welche Sequenznummer folgt auf 15 (0xF)?", ["0", "16", "1", "15"], "Die Nummer ist 4 Bit lang und läuft über."),
   mc("Warum braucht man ISO-TP überhaupt?", ["Diagnosenachrichten sind oft länger als ein Frame", "CAN kann keine Zahlen übertragen", "Um Fehler zu verschlüsseln", "Damit OBD-Buchsen kleiner werden"], "Ein klassischer CAN-Frame trägt nur 8 Byte.")]),
 L("diag.m7.l2", "DoIP: Diagnose über Ethernet", 6, [
  "Steuergeräte-Software wird immer größer. Über CAN dauert das Flashen vieler Gigabyte zu lange. Diagnostics over IP (DoIP, ISO 13400) bringt UDS auf Ethernet.",
  "## So funktioniert es",
  "Der Tester verbindet sich über Ethernet mit dem Fahrzeug, typischerweise mit einem zentralen DoIP-Gateway. Nach Fahrzeugsuche (Vehicle Identification) und Routing Activation leitet das Gateway UDS-Nachrichten an die Zielsteuergeräte weiter, auch an solche hinter CAN.",
  "## Technik",
  "DoIP nutzt TCP und UDP auf Port 13400. Jede Nachricht hat einen kleinen DoIP-Header mit Typ und Länge, Steuergeräte werden über logische Adressen angesprochen.",
  "## Vorteile",
  "Viel höhere Datenrate, Flashen mehrerer Steuergeräte parallel und Diagnose über größere Entfernung, etwa am Bandende oder (abgesichert) aus der Ferne. Physikalisch kann der Zugang über die OBD-Buchse erfolgen, deren freie Pins der Hersteller dafür belegt."],
  ["DoIP (ISO 13400): UDS über Ethernet, Port 13400.", "Ablauf: Fahrzeugsuche → Routing Activation → UDS.", "Vorteil: schnelles, paralleles Flashen."],
  [S_13400],
  [card("DoIP", "Diagnostics over Internet Protocol nach ISO 13400."), card("Routing Activation", "DoIP-Schritt, nach dem das Gateway Diagnosenachrichten weiterleitet."), card("Port 13400", "Standardport von DoIP für TCP und UDP.")],
  [mc("Welche Norm beschreibt DoIP?", ["ISO 13400", "ISO 14229", "ISO 15765", "SAE J1962"], "ISO 14229 ist UDS selbst, 15765 der CAN-Transport."),
   mc("Welchen Port nutzt DoIP standardmäßig?", ["13400", "80", "443", "1234"], "Der Port entspricht der Normnummer."),
   mc("Welcher Schritt kommt vor der UDS-Kommunikation?", ["Routing Activation", "SecurityAccess 0x27", "ECUReset", "ClearDTC"], "Erst danach leitet das Gateway weiter."),
   mc("Was ist der Hauptvorteil von DoIP?", ["Viel schnelleres Flashen", "Keine Kabel mehr nötig", "Kein UDS mehr nötig", "Geringere Stromaufnahme"], "Ethernet bietet ein Vielfaches der CAN-Datenrate."),
   mc("Können Steuergeräte hinter CAN per DoIP erreicht werden?", ["Ja, über das Gateway", "Nein, nur Ethernet-Steuergeräte", "Nur mit einer zweiten Buchse", "Nur in der Programmiersitzung"], "Das Gateway übersetzt zwischen Ethernet und CAN.")]),
 L("diag.m7.l3", "Diagnosedaten: ODX, OTX und SOVD", 6, [
  "Ein Tester muss wissen, welche Dienste ein Steuergerät kann, was die Bytes bedeuten und welche Abläufe gelten. Dafür gibt es standardisierte Beschreibungsformate.",
  "## ODX",
  "Open Diagnostic Data Exchange (ODX, ISO 22901) beschreibt in XML die Diagnoseschnittstelle: Dienste, DIDs, DTCs mit Texten, Umrechnungen, Sitzungen und Flash-Daten. Ein Tester liest die ODX-Daten und kann damit jedes beschriebene Steuergerät bedienen.",
  "## OTX",
  "Open Test sequence eXchange (OTX, ISO 13209) beschreibt Prüfabläufe: geführte Fehlersuche, Bandende-Prüfungen oder Inbetriebnahme, unabhängig vom Testerprogramm.",
  "## SOVD",
  "Service-Oriented Vehicle Diagnostics (SOVD, von ASAM) ist eine moderne REST-Schnittstelle über HTTP. Sie passt zu Fahrzeugen mit Zentralrechnern und Software-Diensten und erlaubt Diagnose lokal, in der Werkstatt oder aus der Ferne. UDS bleibt für klassische Steuergeräte darunter bestehen.",
  "## Schnittstellen zur Hardware",
  "Zwischen Tester-Software und Fahrzeug sitzt ein Kommunikationsadapter (VCI). Genormte Programmierschnittstellen wie SAE J2534 (Pass-Thru) oder ISO 22900 (D-PDU API) erlauben, verschiedene Adapter zu nutzen."],
  ["ODX: Beschreibung der Diagnoseschnittstelle in XML.", "OTX: Beschreibung von Prüfabläufen.", "SOVD: REST-basierte Diagnose für moderne Architekturen."],
  [S_ASAM],
  [card("ODX", "Open Diagnostic Data Exchange (ISO 22901): XML-Beschreibung von Diagnosediensten, DIDs, DTCs."), card("OTX", "Open Test sequence eXchange (ISO 13209): Beschreibung von Prüfabläufen."), card("SOVD", "Service-Oriented Vehicle Diagnostics: REST-API für Fahrzeugdiagnose (ASAM)."), card("VCI", "Vehicle Communication Interface: Adapter zwischen Tester und Fahrzeug.")],
  [mc("Was beschreibt ODX?", ["Die Diagnoseschnittstelle eines Steuergeräts", "Abgasgrenzwerte", "Die Form der OBD-Buchse", "Das Fahrwerk"], "Dienste, DIDs, DTCs, Umrechnungen und mehr."),
   mc("Wofür ist OTX gedacht?", ["Prüfabläufe beschreiben", "CAN-Frames zerlegen", "Schlüssel berechnen", "Fehler entprellen"], "Etwa geführte Fehlersuche oder Bandende-Prüfung."),
   mc("Welche Technik nutzt SOVD?", ["REST über HTTP", "K-Leitung", "LIN-Bus", "Analoge Spannungen"], "Passend für Zentralrechner und Fernzugriff."),
   mc("Was ist SAE J2534?", ["Eine Pass-Thru-Programmierschnittstelle", "Ein Abgasgrenzwert", "Ein Fehlercode", "Ein Bussystem"], "Sie macht Adapter austauschbar."),
   mc("Ersetzt SOVD UDS vollständig?", ["Nein, UDS bleibt für klassische Steuergeräte", "Ja, ab sofort überall", "Ja, aber nur bei Diesel", "Nein, SOVD ist nur für Motorräder"], "Beide existieren nebeneinander.")])
])

M8 = M("diag.m8", 3, "Diagnose in der Praxis", "Systematische Fehlersuche, Flashen, Ferndiagnose und Zugangsregeln.", [
 L("diag.m8.l1", "Systematische Fehlersuche", 6, [
  "Gute Diagnose ist ein Vorgehen, kein Ratespiel.",
  "## Der Ablauf",
  "1. Beanstandung verstehen: Was, wann, wie oft? 2. Fehlerspeicher aller Steuergeräte lesen, nicht nur des Motors. 3. Status und Umgebungsdaten auswerten: aktuell oder sporadisch? 4. Messwerte und Stellgliedtests nutzen. 5. Gezielt messen, etwa Spannung, Widerstand oder Signalverlauf. 6. Reparieren. 7. Löschen und mit einer Probefahrt bestätigen.",
  "## Folgefehler erkennen",
  "Fällt die Versorgung eines Sensors aus, melden oft mehrere Steuergeräte Fehler. Ein Busfehler erzeugt viele U-Codes. Wer zuerst den gemeinsamen Nenner sucht, spart Zeit.",
  "## Geführte Fehlersuche",
  "Hersteller-Tester bieten geführte Prüfpläne: Sie fragen Messwerte ab, schlagen Messungen vor und grenzen Schritt für Schritt ein. Die Abläufe sind oft in OTX oder ähnlichen Formaten beschrieben."],
  ["Beanstandung → alle Fehlerspeicher → Status/Daten → Messen → Reparieren → Bestätigen.", "Folgefehler: gemeinsamen Nenner suchen.", "Geführte Fehlersuche grenzt systematisch ein."],
  [S_REIF],
  [card("Sporadischer Fehler", "Fehler, der nur zeitweise auftritt; Status testFailed = 0, aber confirmed = 1."), card("Folgefehler", "Fehler, der durch einen anderen Fehler ausgelöst wird, z. B. viele U-Codes bei Busstörung.")],
  [order("Ordne die Schritte einer systematischen Fehlersuche.", ["Beanstandung verstehen", "Fehlerspeicher aller Steuergeräte lesen", "Status und Umgebungsdaten auswerten", "Gezielt messen", "Reparieren und Probefahrt"], "Erst Informationen sammeln, dann eingreifen."),
   mc("Viele Steuergeräte melden U-Codes gleichzeitig. Was liegt nahe?", ["Ein gemeinsames Bus- oder Versorgungsproblem", "Alle Steuergeräte sind defekt", "Der Tester ist falsch eingestellt", "Der Kraftstoff ist schlecht"], "Ein gemeinsamer Nenner erklärt viele Folgefehler."),
   mc("Status: testFailed = 0, confirmed = 1. Was bedeutet das?", ["Der Fehler ist gerade nicht aktiv", "Der Fehler ist gerade aktiv", "Der Fehler wurde nie bestätigt", "Der Test lief nie"], "Typisch für sporadische oder behobene Fehler."),
   mc("Warum liest man alle Steuergeräte aus?", ["Ursache und Folgefehler können verteilt sein", "Weil es gesetzlich vorgeschrieben ist", "Weil der Motor sonst nicht startet", "Weil der Tester sonst blockiert"], "Die eigentliche Ursache liegt oft in einem anderen Steuergerät."),
   mc("Wie bestätigt man eine Reparatur?", ["Löschen und Monitor erneut laufen lassen", "Nur den Fehler löschen", "Batterie abklemmen", "Kilometerstand prüfen"], "Erst ein erneutes „bestanden“ zeigt den Erfolg.")]),
 L("diag.m8.l2", "Software-Update in Werkstatt und per OTA", 6, [
  "Viele Fehler werden heute durch Software behoben. Ein Update läuft in der Werkstatt über den Tester oder drahtlos als Over-the-Air-Update (OTA).",
  "## Werkstatt-Flashen",
  "Ablauf: Batterieladegerät anschließen (Spannung stabil halten), in die Programmiersitzung wechseln, Zugriff freischalten, Speicher löschen, Daten übertragen, Prüfsumme und Signatur prüfen lassen, Reset, danach codieren und Grundeinstellungen durchführen.",
  "## OTA",
  "Bei OTA lädt das Fahrzeug das Update über Mobilfunk, prüft es und installiert es zu einem sicheren Zeitpunkt, oft in eine zweite Speicherbank (A/B), damit bei einem Fehler die alte Version weiterläuft.",
  "## Regeln",
  "Für neue Fahrzeuge in der EU schreibt die UN-Regelung R156 ein Software-Update-Managementsystem vor: Hersteller müssen dokumentieren, welche Software im Fahrzeug ist (z. B. über eine Software-Identifikationsnummer, RXSWIN), Updates absichern und Auswirkungen auf die Typgenehmigung bewerten."],
  ["Flashen: Spannung stabil, Programmiersitzung, Freischalten, Löschen, Übertragen, Prüfen, Reset.", "OTA oft mit A/B-Speicher für sichere Rückfallebene.", "UN R156 verlangt ein Software-Update-Managementsystem."],
  [S_14229, S_R156],
  [card("OTA-Update", "Software-Update über Mobilfunk, ohne Werkstattbesuch."), card("A/B-Partition", "Zwei Speicherbänke: Update in die inaktive Bank, Umschalten erst nach Erfolg."), card("RXSWIN", "Software-Identifikationsnummer nach R156, die genehmigungsrelevante Software kennzeichnet.")],
  [mc("Warum schließt man beim Flashen ein Ladegerät an?", ["Spannungseinbrüche können das Flashen abbrechen", "Damit die Software schneller lädt", "Weil das Gesetz es verlangt", "Damit der Motor läuft"], "Ein Abbruch kann das Steuergerät im Bootloader zurücklassen."),
   mc("Wozu dient eine A/B-Partition?", ["Bei Fehler weiter mit alter Version", "Doppelte Rechenleistung", "Zwei Fahrer speichern", "Mehr Platz für Musik"], "Umgeschaltet wird erst nach erfolgreicher Prüfung."),
   mc("Welche Regelung fordert ein Software-Update-Managementsystem?", ["UN R156", "UN R155", "Euro 7", "SAE J1962"], "R155 betrifft Cybersecurity."),
   mc("Was folgt nach dem Flashen oft?", ["Codieren und Grundeinstellungen", "Nichts mehr", "Abgasuntersuchung", "Reifenwechsel"], "Neue Software braucht passende Konfiguration und Anlernwerte."),
   mc("Was ist ein Vorteil von OTA-Updates?", ["Kein Werkstattbesuch nötig", "Keine Absicherung nötig", "Funktioniert ohne Speicher", "Keine Prüfung der Software"], "Absicherung und Prüfung bleiben Pflicht.")]),
 L("diag.m8.l3", "Ferndiagnose und Zugang", 6, [
  "Vernetzte Fahrzeuge können Diagnosedaten auch aus der Ferne liefern: zur Pannenhilfe, zur Vorbereitung eines Werkstatttermins oder zur Flottenüberwachung.",
  "## Möglichkeiten",
  "Das Fahrzeug meldet Fehler an ein Backend, die Werkstatt sieht sie vor dem Termin und bestellt passende Teile. Manche Hersteller bieten Fernzugriff durch geschulte Experten, die mit der Werkstatt zusammen diagnostizieren.",
  "## Datenschutz und Sicherheit",
  "Diagnosedaten können Rückschlüsse auf Fahrer zulassen. Übertragung und Speicherung unterliegen dem Datenschutz (in der EU der DSGVO), und der Fernzugang muss nach UN R155 abgesichert sein.",
  "## Wer darf was?",
  "Unabhängige Werkstätten haben in der EU ein Recht auf Zugang zu Reparatur- und Wartungsinformationen (RMI). Für sicherheitsrelevante Funktionen, etwa an der Wegfahrsperre, gibt es ein besonderes Zulassungsverfahren für Werkstattpersonal (SERMI). Viele Hersteller verlangen für erweiterte Diagnose eine Anmeldung mit Benutzerkonto."],
  ["Ferndiagnose: Fehler vorab sehen, Teile vorbereiten, Experten zuschalten.", "Datenschutz (DSGVO) und Cybersecurity (R155) gelten.", "EU: Zugangsrecht unabhängiger Werkstätten; SERMI für sicherheitsrelevante Funktionen."],
  [S_R155, S("Verordnung (EU) 2018/858, Kapitel XIV: Zugang zu Reparatur- und Wartungsinformationen", "https://eur-lex.europa.eu/eli/reg/2018/858/oj")],
  [card("RMI", "Repair and Maintenance Information: Reparatur- und Wartungsinformationen, zu denen unabhängige Werkstätten Zugang haben müssen."), card("SERMI", "Zulassungsverfahren für Werkstattpersonal, das sicherheitsrelevante Funktionen (z. B. Wegfahrsperre) bearbeiten darf.")],
  [mc("Was ist ein Nutzen der Ferndiagnose?", ["Teile vor dem Werkstatttermin bestellen", "Fahrzeug fährt schneller", "Keine Wartung mehr nötig", "Fehler verschwinden automatisch"], "Die Werkstatt ist vorbereitet, bevor das Auto kommt."),
   mc("Welches Recht haben unabhängige Werkstätten in der EU?", ["Zugang zu Reparaturinformationen", "Kostenlose Ersatzteile", "Zugriff auf alle Kundendaten", "Software beliebig zu ändern"], "Geregelt in der Typgenehmigungsverordnung 2018/858."),
   mc("Wofür gibt es SERMI?", ["Sicherheitsrelevante Funktionen wie Wegfahrsperre", "Abgasmessungen", "Reifendruckkontrolle", "Lackierarbeiten"], "Nur geprüftes Personal soll solche Funktionen bearbeiten."),
   mc("Welche Regel gilt für Diagnosedaten mit Personenbezug in der EU?", ["Die DSGVO", "Keine Regel", "Nur die Straßenverkehrsordnung", "Nur interne Herstellerregeln"], "Personenbezogene Daten sind geschützt."),
   mc("Was verlangt UN R155 für den Fernzugang?", ["Absicherung gegen Cyberangriffe", "Eine bestimmte Bitrate", "Eine zweite OBD-Buchse", "Einen festen Werkstattpartner"], "R155 fordert ein Cybersecurity-Managementsystem.")])
])

COURSE = {"id": "diag", "title": "Fahrzeugdiagnose: OBD und UDS",
  "sub": "Von der Motorkontrollleuchte bis zum Flashen: Fehlercodes, OBD-Dienste, UDS, DoIP und Praxis",
  "audience": "Alle, die Fahrzeugdiagnose verstehen wollen, von Werkstatt bis Steuergeräte-Entwicklung",
  "modules": [M1, M2, M3, M4, M5, M6, M7, M8]}
